public(package) fun update_asset_borrow(self: &mut EModeGroup, coin: TypeName, old_value: Decimal, new_value: Decimal): Decimal {
    assert!(self.assets_borrows.supports_type(coin), error::emode_group_does_not_support_asset());

    let current_borrow = self.assets_borrows.load_mut_by_type(coin);
    // using saturating_sub, if the value is below 0, just let it be zero
    let new_borrow = new_value.add(*current_borrow).saturating_sub(old_value);

    *current_borrow = new_borrow;
    new_borrow
}

public(package) fun borrow_amount(self: &EModeGroup, coin: TypeName): Decimal {
    assert!(self.assets_borrows.supports_type(coin), error::emode_group_does_not_support_asset());
    *self.assets_borrows.load_by_type(coin)
}

